+  Future<void> _retryFinishedRound(int generation) async {
+    if (!_currentOwner() ||
+        generation != _round ||
+        _controller == null ||
+        _nativeOpening ||
+        _game.phase == ConnectPhase.playing) return;
+    setState(() => _busy = true);
+    try {
+      // The final move is already saved. Retry only its existing idempotent
+      // reward and receipt; never drop another piece or invent an award.
+      await _controller!.settleReward();
+    } catch (_) {
+      if (!_currentOwner() || generation != _round) return;
+      _saveError();
+      _clock.schedule(Duration.zero,
+          () => unawaited(_retryFinishedRound(generation)));
+      return;
+    }
+    if (!_currentOwner() || generation != _round || _nativeOpening) return;
+    // Home/Pause may have arrived while the wallet was being confirmed.
+    // Deliver the already settled result only when the same clock resumes.
+    _clock.schedule(Duration.zero, () {
+      if (!_currentOwner() || generation != _round || _nativeOpening) return;
+      _finish();
+    });
+  }
